(function () {
  var LOCALES = ["ja", "en", "zh", "ko", "es", "de"];
  var COOKIE = "PARAGLIDE_LOCALE";
  var DICT = {"en":{"nav.how":"How it works","nav.features":"Features","nav.infra":"Infrastructure","nav.security":"Security","nav.cta":"Try the demo","hero.sub":"A development platform that measures and drives your codebase understanding","hero.h1":"Measure <span class='text-know'>understanding</span> with quizzes and visualize it on an <span class='text-know'>understanding map</span>.<br class='hidden sm:block' />Improve low-quality code with <span class='text-code'>AI-generated fix PRs</span>.","hero.lead":"AI agents leverage <strong class='font-semibold text-white'>sub-agents, MCP, and Hooks</strong> to analyze your repository from every angle.<br class='hidden lg:block' />From extracting features and measuring understanding to detecting code quality issues and proposing fixes, everything is automated end to end.","hero.chip1":"Advanced repository exploration with AI agents × MCP","hero.chip2":"Easy login via GitHub integration","hero.chip3":"Automatic masking of PII and secrets","hero.chip4":"Mobile-friendly","hero.chip5":"Scalable infrastructure","challenge.h2":"\"Understanding debt\" is piling up fast in the AI era","challenge.lead":"As tools like Claude Code, Codex, and Gemini CLI become widespread, the \"development\" and \"operations\" cycle keeps accelerating, but in that rush <strong class='text-white'>understanding the code gets pushed aside</strong>, and \"understanding debt\"—the inability to explain what AI-generated code does or why it was written that way—accumulates rapidly.","challenge.c1t":"Understanding left behind by \"just make it work\"","challenge.c1d":"Deadlines and deployment speed take priority, and the step of understanding the code is skipped. Work moves forward while no one but the author knows what's inside.","challenge.c2t":"Thinking skipped by leaving it to AI","challenge.c2d":"Plausible-looking generated code is trusted as-is and shipped to production without ever asking \"why is it written this way?\" Unexplained code keeps growing.","challenge.c3t":"\"Do you understand it?\" goes unmeasured","challenge.c3d":"Reviews and tests measure quality, but not people's understanding. There's no telling where to start or how urgent it is.","audience.h2":"Who it's for","audience.a1t":"Tech leads / Managers","audience.a1d":"Identify where team members' understanding is weak, and prioritize reviews and learning.","audience.a2t":"Onboarding leads / New joiners","audience.a2d":"Systematically track where to start understanding, with learning units and quizzes.","flow.h2":"Build the resolution of technical debt and understanding debt into your development and operations cycle","flow.sub":"End to end, from analysis to measuring understanding, detecting quality issues, and learning and improvement. Repay debt with the twin engines of \"measure → learn\" and \"detect → improve\".","flow.s0t":"Repository analysis","flow.s0d":"AI agents use MCP to explore the codebase across the board. They cluster files into functional units and grasp the tech stack and dependencies.","flow.track_know":"Understanding debt","flow.track_code":"Technical debt","flow.s1t":"Generate and administer quizzes","flow.s1d":"Automatically generate understanding quizzes for each feature. From the answers, objectively measure \"who understands what\" at the file level.","flow.s2t":"Generate a learning plan","flow.s2d":"Tailored to features that are poorly understood, the agent automatically assembles a learning plan including walkthroughs of the relevant code and technical documentation.","flow.s3t":"Detect low-quality code","flow.s3d":"Analyze duplication, complexity, dead code, traces of AI generation, and more to identify low-quality, high-priority files.","flow.s4t":"Propose code improvements","flow.s4d":"For low-quality code, AI automatically creates fix PRs. It can also open Issues with assignees.","flow.s5t":"Understanding and quality improve","flow.s5d":"With the twin engines of \"measure → learn\" and \"detect → improve\", eliminate knowledge silos and continuously improve your codebase's understanding and code quality.","core.h2":"Three core capabilities","core.c1t":"Advanced repository analysis by AI agents","core.c1d":"Agents built with Google ADK explore the repository using MCP (Serena / CodeGraphContext / Semgrep / GitHub). They automate generating per-feature learning plans and quizzes, detecting low-quality code, and creating fix plans.","core.c2t":"Visualize understanding debt × improve it with quizzes and learning","core.c2d":"Cluster source code into functional units and generate a learning plan and understanding check test for each feature. Visualize understanding debt with a graph and actively repay it through the closed loop of quiz → learning.","core.c3t":"Recommendations and automatic fixes for low-quality code","core.c3d":"For the low-quality code detected during analysis, open recommendations as GitHub Issues. You can assign owners and even automatically create fix PRs.","core.oplabel":"Features built for real-world operation","core.pill1":"GitHub SSO authentication and authorization","core.pill2":"Project management","core.pill3":"Onboarding guide","core.pill4":"Rich keyboard shortcuts","core.pill5":"User management by administrators","core.pill6":"Billing control via credit grants","core.pill7":"i18n multilingual support","core.pill8":"View release history","features.h2":"What the app can do","features.sub":"From analysis to dashboards, visualization, and improvement—all in a single workspace.","features.f1t":"Dashboard — the big picture at a glance","features.f1lead":"Check your repository's understanding and code quality on a single screen.","features.f1li1":"・The <strong class='text-white'>matrix</strong> organizes files along two axes: \"understanding × code quality\". Files low on both are the priority areas to improve.","features.f1li2":"・<strong class='text-white'>Metrics</strong> show understanding, the number of low-quality files, and the number of fixed files, each with its change over time.","features.f1li3":"・The <strong class='text-white'>trend graph</strong> shows how code quality and understanding change over time.","features.f1li4":"・The <strong class='text-white'>priority list</strong> lists the files that need attention.","features.f1tag1":"Two axes: understanding × quality","features.f1tag2":"Hotspot visualization","features.f1tag3":"Priority score","features.f2t":"Understanding map — who understands what, and where","features.f2lead":"Visualize each user's understanding by feature and file with a graph. Two views are available: <strong class='font-semibold text-white'>map</strong> and <strong class='font-semibold text-white'>list</strong>. <strong class='font-semibold text-white'>Feature chips</strong> let you narrow down to just the files involved in a specific feature. In the map view, nodes = files, lines = dependencies, and color = understanding; selecting a node highlights its adjacent files.","features.f2leg1":"Understood","features.f2leg2":"Partially understood","features.f2leg3":"Not understood","features.f2leg4":"Not started","features.f2tag1":"Graph visualization with CodeGraphContext","features.f2tag2":"File dependency analysis","features.f2tag3":"Feature clustering","features.f3t":"Code quality map — an overview of the quality distribution","features.f3lead":"Browse source code file by file and see which files have what room for improvement.","features.f3li1":"・Select a file from the <strong class='text-white'>file tree</strong> on the left. Files with room for improvement carry a <strong class='text-white'>badge</strong>.","features.f3li2":"・The contents of the selected file appear on the right. <strong class='text-white'>Flagged spots are highlighted</strong> so you can check them right there.","features.f3tag1":"Analysis with Serena MCP (LSP)","features.f3tag2":"Static analysis with Semgrep","features.f3tag3":"Dead code detection","features.f4t":"Quizzes and learning — measure and deepen understanding","features.f4lead":"Take per-feature learning plans and check your understanding with quizzes.","features.f4li1":"<strong class='text-white'>・Learning plan list</strong> — Check each plan's status and understanding, along with your overall learning progress. Flag units you want to review, and they're gathered at the top of the list.","features.f4li2":"<strong class='text-white'>・Open a lesson</strong> — Learn repository-specific features through walkthroughs, and refer to the official documentation of related technologies. Understand key processing step by step.","features.f4li3":"<strong class='text-white'>・Check your understanding</strong> — Take a check quiz. Flag questions you want to review later, and repeatedly review your weak points with retests narrowed to flagged or incorrect answers.","features.f4tag1":"ADK agents generate learning plans and quizzes","features.f4tag2":"Learn with the twin engines of repository-specific × tech stack","features.f4tag3":"Flagging and retesting incorrect answers","features.f5t":"Code improvement — give back via PRs / Issues","features.f5lead":"Review improvement points file by file, and automatically generate AI fix Pull Requests or create Issues.","features.f5li1":"・Narrow down with <strong class='text-white'>filters</strong> and sort <strong class='text-white'>by priority</strong>. Click an improvement target to open its detail screen.","features.f5li2":"・On the detail screen, the problematic code is highlighted, and you can review the <strong class='text-white'>reason for the low quality, priority, and estimated effort</strong>.","features.f5li3":"・Choose how to improve: <strong class='text-white'>\"Have AI automatically create a fix PR\"</strong> or <strong class='text-white'>\"Assign an owner and create an Issue\"</strong>.","features.f5tag1":"AI generates the fix patch","features.f5tag2":"Automatic fix PR generation","features.f5tag3":"GitHub Issue creation","infra.h2":"Infrastructure","infra.lead":"Using Cloud Tasks, analysis is offloaded to asynchronous workers. Cloud Run auto-scales with load.<br class='hidden sm:block' />Analysis achieves comprehensive, efficient repository exploration by leveraging agents built with ADK and MCP.<br class='hidden sm:block' />Security is ensured with rate limiting via Cloud Armor, plus Secret Manager and Cloud DLP. Infrastructure is codified as IaC with Terraform.<br class='hidden sm:block' />During development, CI/CD runs everything from testing to deployment, plus automatic application of linters/formatters and automated code review by Gemini, keeping code quality high.","security.h2":"What we care about in security","security.s1t":"Authentication and sessions","security.s1d":"GitHub SSO using JWT tokens. Secure session management using access and refresh tokens. Session timeout after 30 minutes of inactivity.","security.s2t":"Same-origin delivery and web vulnerability protection","security.s2d":"Serving the UI and API from the same origin removes the need for CORS configuration. On top of that, we implement the protections web apps need, such as against XSS, CSRF, and SSRF.","security.s3t":"A key-free design","security.s3d":"Workload Identity Federation eliminates long-lived credentials. Secrets at deploy time are injected via GitHub Secrets, and at runtime they are consolidated and managed in Secret Manager.","security.s4t":"Rate limiting at the edge and within the app","security.s4d":"Cloud Armor limits excessive requests before they reach the app. Within the app, administrators can grant and manage credits for repository analysis, preventing abuse of costly analysis processing.","security.s5t":"Masking of agent input","security.s5d":"When feeding information to agents, we mask PII and secrets with Cloud DLP (Sensitive Data Protection) and detect-secrets before sending.","security.s6t":"Vulnerability scanning","security.s6d":"We perform OWASP-compliant application vulnerability scanning as well as container image vulnerability scanning using Trivy.","mobile.h2":"Check understanding anytime, even on your phone","mobile.sub":"With responsive design, you can use the main features as-is from a smartphone.<br class='hidden sm:block' />On the go or between reviews, you can check the understanding map, grasp code quality, and take quizzes.","mobile.l1":"Dashboard","mobile.l2":"Understanding map","mobile.l3":"Code quality map","mobile.l4":"Quizzes and learning","mobile.l5":"Code improvement","stack.h2":"Tech stack","cta.h2":"Make your team's understanding visible, starting today","cta.p":"Just connect a GitHub repository and analyze it. You can tackle both understanding debt and technical debt, and slot it right into your daily development and operations (DevOps) cycle.","cta.btn":"Connect a repository to get started","footer.privacy":"Privacy Policy","privacy.title":"Privacy Policy","privacy.intro":"DevDebtOps (hereinafter the \"Service\") establishes the following privacy policy (hereinafter this \"Policy\") regarding the handling of the personal information of users of the Service (hereinafter \"users\") and the data that users provide.","privacy.1t":"1. Information we collect","privacy.1li1":"<span class='text-white'>Account information</span>: Your username, email address, public profile, and the like, obtained at login via GitHub integration.","privacy.1li2":"<span class='text-white'>Data to be analyzed</span>: The source code and metadata (file structure, commit history, dependencies, etc.) of the GitHub repositories the user connects.","privacy.1li3":"<span class='text-white'>Usage data</span>: Quiz answers and learning progress, operation logs, and access logs (IP address, browser information, access date and time, etc.).","privacy.2t":"2. Purposes of use","privacy.2li1":"Providing and operating the Service (measuring understanding, code analysis, generating learning plans and quizzes, proposing code improvements, etc.).","privacy.2li2":"Improving the quality of the Service, enhancing features, and addressing defects.","privacy.2li3":"Preventing misuse, ensuring security, and analyzing usage.","privacy.3t":"3. Integration with external services","privacy.3p":"The Service integrates with the following external services to provide its features. The handling of information at those destinations follows the rules of each service.","privacy.3li1":"<span class='text-white'>GitHub</span>: For authentication and repository integration.","privacy.3li2":"<span class='text-white'>AI analysis platforms (Google Vertex AI / Gemini, etc.)</span>: For code analysis and learning content generation, we send code and the like to the extent necessary. Before sending, we mask personal information (PII) and secrets.","privacy.4t":"4. Provision to third parties","privacy.4p":"Except as required by law or where there is another legitimate reason, we do not provide personal information to third parties without the user's consent.","privacy.5t":"5. Use via organizational accounts","privacy.5p":"When a user uses the Service through an organization they belong to (a team, company, etc.), the administrators of that organization may be able to access members' account settings and data such as analysis results, understanding, and learning status. Handling under organization-level use also follows that organization's policies.","privacy.6t":"6. Storage and security","privacy.6p":"The information we collect is managed on cloud infrastructure (Google Cloud) after we take appropriate technical and organizational measures such as encryption and access control.","privacy.7t":"7. Retention period and deletion","privacy.7p":"We retain information for the period necessary to achieve the purposes of use, and after that period elapses or upon a user's request, we appropriately delete or anonymize it. Upon account deletion, the associated data is deleted.","privacy.8t":"8. Cross-border data transfers","privacy.8p":"The Service uses cloud infrastructure (Google Cloud) and AI analysis platforms, and a user's data may be stored and processed on servers outside Japan (such as in the United States). Even in such cases, we take appropriate protective measures in accordance with applicable law.","privacy.9t":"9. Legal bases for processing (for users in the EEA / UK)","privacy.9p":"For users in the European Economic Area (EEA) or the UK, we process personal data under the GDPR and similar laws on one of the following legal bases: (1) performance of a contract, (2) compliance with legal obligations, (3) legitimate interests (such as ensuring the safety and improvement of the Service), or (4) the user's consent. Processing based on consent may be withdrawn at any time.","privacy.10t":"10. Users' rights","privacy.10p":"Users may request disclosure, correction, deletion, suspension of use, and the like regarding their own personal information. When making a request, we may ask you to provide additional information to verify your identity. Depending on the laws of your region (such as the GDPR and CCPA), you may be granted additional rights such as data portability and the right to object to processing. Please contact our support desk.","privacy.11t":"11. Use of cookies","privacy.11p":"The Service uses cookies necessary to maintain your login state and ensure security (essential cookies). We do not use cookies for advertising or tracking purposes. You can control cookies through your browser settings or DNT / GPC signals, but disabling essential cookies may make some features unavailable.","privacy.12t":"12. Revisions to this Policy","privacy.12p":"This Policy may be revised in response to changes in law or in the content of the Service. In the event of a significant change, we will provide notice on the Service.","privacy.13t":"13. Contact","privacy.13p":"For inquiries regarding this Policy, please contact the operator of the Service.","privacy.updated":"Last updated: July 6, 2026"},"zh":{"nav.how":"工作原理","nav.features":"功能","nav.infra":"基础设施","nav.security":"安全","nav.cta":"体验演示","hero.sub":"实测并促进代码库理解程度的开发平台","hero.h1":"通过测验实测<span class='text-know'>理解度</span>，并以<span class='text-know'>理解度地图</span>可视化。<br class='hidden sm:block' />借助 <span class='text-code'>AI 自动修复 PR</span> 改善低质量代码。","hero.lead":"AI 智能体运用<strong class='font-semibold text-white'>子智能体、MCP 与 Hook</strong>对仓库进行多维度解析。<br class='hidden lg:block' />从功能提取到理解度实测、代码质量检测，再到修复建议，全流程一体化自动完成。","hero.chip1":"AI 智能体 × MCP 实现高级仓库探索","hero.chip2":"通过 GitHub 集成轻松登录","hero.chip3":"自动屏蔽 PII 与密钥","hero.chip4":"支持移动端","hero.chip5":"可扩展的基础设施架构","challenge.h2":"AI 时代急速累积的「理解负债」","challenge.lead":"随着 Claude Code、Codex、Gemini CLI 等工具的普及，「开发」与「运维」的循环不断加速，然而在这种速度之下，<strong class='text-white'>「理解」代码却被一再拖延</strong>，无法说明 AI 生成的代码在做什么、为何这样编写的「理解负债」正在急速累积。","challenge.c1t":"「能跑就行」，理解被抛在脑后","challenge.c1d":"交付期与部署速度被优先考虑，理解代码的步骤被省略。除编写者之外无人了解其内容，项目便这样推进。","challenge.c2t":"全权交给 AI，思考被跳过","challenge.c2d":"对看似合理的生成代码照单全收，不去追问「为何这样写」便直接上线。无人理解的代码持续增加。","challenge.c3t":"「是否理解」无从衡量","challenge.c3d":"评审与测试衡量的是质量，却不衡量人的理解程度。既不知从何着手，也无法判断紧急程度。","audience.h2":"适合这样的您","audience.a1t":"技术主管 / 管理者","audience.a1d":"希望掌握团队成员理解薄弱的部分，确定评审与学习的优先级。","audience.a2t":"入职培训负责人 / 新加入成员","audience.a2d":"希望通过学习单元与测验，系统地梳理应从何处开始理解。","flow.h2":"将技术负债与理解负债的化解融入开发与运维循环","flow.sub":"从解析到理解的实测、质量的检测，再到学习与改善，全流程一体化。以「实测 → 学习」和「检测 → 改善」双轮驱动进行偿还。","flow.s0t":"仓库解析","flow.s0d":"AI 智能体使用 MCP 对代码库进行横向探索。将文件群按功能单元聚类，并掌握技术栈与依赖关系。","flow.track_know":"理解负债","flow.track_code":"技术负债","flow.s1t":"生成并实测测验","flow.s1d":"按功能自动生成理解度测验。根据作答以文件为单位客观实测「谁理解了哪些部分」。","flow.s2t":"生成学习计划","flow.s2d":"针对理解较浅的功能，由智能体自动编排包含相关代码演练及技术文档的学习计划。","flow.s3t":"检测低质量代码","flow.s3d":"解析重复、复杂度、死代码、AI 生成痕迹等，识别质量低且优先级高的文件。","flow.s4t":"提出代码改善方案","flow.s4d":"针对低质量代码，AI 自动创建修复 PR。也支持创建并指派负责人的 Issue。","flow.s5t":"理解度与质量提升","flow.s5d":"以「实测 → 学习」和「检测 → 改善」双轮驱动消除属人化，持续提升代码库的理解度与代码质量。","core.h2":"三大核心功能","core.c1t":"由 AI 智能体实现的高级仓库解析","core.c1d":"使用 Google ADK 构建的智能体运用 MCP（Serena / CodeGraphContext / Semgrep / GitHub）探索仓库。将按功能生成学习计划与测验、检测低质量代码并制定修复计划等工作全部自动化。","core.c2t":"理解负债可视化 × 通过测验与学习改善","core.c2d":"将源代码按功能单元聚类，并按功能生成学习计划与理解度确认测试。以图形可视化理解负债，通过测验 → 学习的闭环主动偿还。","core.c3t":"对低质量代码的推荐建议与自动修复","core.c3d":"针对解析中检测到的低质量代码，以 GitHub Issue 形式提出建议事项。还可进行负责人指派，以及自动创建修复 PR。","core.oplabel":"面向实际运维的功能","core.pill1":"GitHub SSO 认证与授权","core.pill2":"项目管理","core.pill3":"入职引导指南","core.pill4":"丰富的快捷键","core.pill5":"管理员进行用户管理","core.pill6":"通过发放额度控制计费","core.pill7":"i18n 多语言支持","core.pill8":"查看发布历史","features.h2":"应用能做什么","features.sub":"在一个工作区内完成从解析到仪表盘、可视化、改善的全过程。","features.f1t":"Dashboard — 一目了然掌握全局","features.f1lead":"一屏即可确认仓库的理解度与代码质量。","features.f1li1":"・<strong class='text-white'>矩阵</strong>以「理解度 × 代码质量」两轴整理文件。两者都低的文件即应优先改善的领域。","features.f1li2":"・<strong class='text-white'>指标</strong>展示理解度、低质量文件数量、已修复数量，并附带变化量。","features.f1li3":"・通过<strong class='text-white'>趋势图</strong>确认代码质量与理解度随时间的变化。","features.f1li4":"・以<strong class='text-white'>优先处理列表</strong>一览应处理的文件。","features.f1tag1":"理解度 × 质量的双轴","features.f1tag2":"热点可视化","features.f1tag3":"优先处理评分","features.f2t":"理解度地图 — 谁理解了哪些部分","features.f2lead":"按功能与文件，以图形可视化用户的理解度。展示形式有<strong class='font-semibold text-white'>地图</strong>与<strong class='font-semibold text-white'>列表</strong>两种。可通过<strong class='font-semibold text-white'>功能标签</strong>仅筛选出与特定功能相关的文件群。地图展示中，节点＝文件、连线＝依赖关系、颜色＝理解度，选中节点即可高亮显示相邻文件。","features.f2leg1":"已理解","features.f2leg2":"部分理解","features.f2leg3":"未理解","features.f2leg4":"未着手","features.f2tag1":"由 CodeGraphContext 实现的图形可视化","features.f2tag2":"文件间依赖关系解析","features.f2tag3":"功能聚类","features.f3t":"代码质量地图 — 俯瞰质量分布","features.f3lead":"以文件为单位浏览源代码，确认哪些文件存在何种改善空间。","features.f3li1":"・从左侧的<strong class='text-white'>文件树</strong>选择文件。存在改善空间的文件会附有<strong class='text-white'>徽章</strong>。","features.f3li2":"・右侧显示所选文件的内容。<strong class='text-white'>指摘之处会高亮显示</strong>，可当场确认。","features.f3tag1":"由 Serena MCP（LSP）实现的解析","features.f3tag2":"由 Semgrep 实现的静态解析","features.f3tag3":"死代码检测","features.f4t":"测验与学习 — 通过实测加深理解","features.f4lead":"学习各功能的学习计划，并通过确认测验检查理解度。","features.f4li1":"<strong class='text-white'>・学习计划一览</strong> — 确认各计划的状态与理解度，以及整体学习进度。可为想复习的单元加上标记，并汇总至列表顶部。","features.f4li2":"<strong class='text-white'>・打开学习</strong> — 通过演练学习仓库特有的功能，并参考相关技术的官方文档。分阶段理解关键处理逻辑。","features.f4li3":"<strong class='text-white'>・确认理解度</strong> — 参加确认测验。可为想稍后复习的题目加上标记，并通过仅限标记 / 错题的重测反复复习薄弱环节。","features.f4tag1":"由 ADK 智能体生成学习计划与测验","features.f4tag2":"以仓库特有 × 技术栈双轮进行学习","features.f4tag3":"标记与错题重测","features.f5t":"代码改善 — 以 PR / Issue 回馈","features.f5lead":"以文件为单位确认改善之处，可自动生成由 AI 修复的 Pull Request 或创建 Issue。","features.f5li1":"・通过<strong class='text-white'>筛选</strong>缩小范围，并按<strong class='text-white'>优先级排序</strong>。点击改善对象即可进入详情页面。","features.f5li2":"・在详情页面中，问题代码之处会高亮显示，可确认<strong class='text-white'>质量低下的原因、优先级、预估工时</strong>。","features.f5li3":"・改善方式可从<strong class='text-white'>「让 AI 自动创建修复 PR」</strong>或<strong class='text-white'>「指派负责人并创建 Issue」</strong>中选择。","features.f5tag1":"AI 生成修复补丁","features.f5tag2":"自动生成修复 PR","features.f5tag3":"创建 GitHub Issue","infra.h2":"基础设施架构","infra.lead":"运用 Cloud Tasks 将解析分离至异步 worker。Cloud Run 根据负载自动扩缩。<br class='hidden sm:block' />解析借助以 ADK 构建的智能体与 MCP，实现全面且高效的仓库探索。<br class='hidden sm:block' />通过 Cloud Armor 进行限流，并以 Secret Manager 及 Cloud DLP 保障安全。基础设施以 Terraform 实现 IaC 化。<br class='hidden sm:block' />开发时，CI/CD 除完成测试至部署外，还会自动应用 linter / formatter 并由 Gemini 进行自动代码评审，从而将代码质量维持在高水准。","security.h2":"在安全方面的坚持","security.s1t":"认证与会话","security.s1d":"使用 JWT 令牌的 GitHub SSO。使用访问令牌与刷新令牌的安全会话管理。30 分钟无操作时的会话超时。","security.s2t":"同源分发与 Web 漏洞防护","security.s2d":"通过将 UI 与 API 以同源分发，无需 CORS 配置。此外，还实施了 XSS、CSRF、SSRF 等 Web 应用所需的防护措施。","security.s3t":"不持有密钥的设计","security.s3d":"通过 Workload Identity Federation 排除长期凭据。部署时的密钥通过 GitHub Secrets 注入，运行时则汇集至 Secret Manager 统一管理。","security.s4t":"边缘及应用内的限流","security.s4d":"通过 Cloud Armor 在应用前端限制过量请求。在应用内，管理员可发放并管理仓库解析的额度，防止高成本解析处理被滥用。","security.s5t":"智能体输入的屏蔽","security.s5d":"在向智能体提供信息时，先使用 Cloud DLP（Sensitive Data Protection）与 detect-secrets 屏蔽 PII 与密钥，然后再发送。","security.s6t":"漏洞扫描","security.s6d":"实施符合 OWASP 标准的应用程序漏洞扫描，以及使用 Trivy 的容器镜像漏洞扫描。","mobile.h2":"在手机上，也能随时查看理解度","mobile.sub":"响应式设计，可从智能手机直接使用主要功能。<br class='hidden sm:block' />即使在移动途中或评审间隙，也可确认理解度地图、掌握代码质量、参加测验。","mobile.l1":"Dashboard","mobile.l2":"理解度地图","mobile.l3":"代码质量地图","mobile.l4":"测验与学习","mobile.l5":"代码改善","stack.h2":"技术栈","cta.h2":"从今天起，让团队的理解度可视化","cta.p":"只需连接 GitHub 仓库并进行解析即可。既能应对理解负债，也能应对技术负债，可直接融入日常的开发与运维（DevOps）循环。","cta.btn":"连接仓库开始使用","footer.privacy":"隐私政策","privacy.title":"隐私政策","privacy.intro":"DevDebtOps（以下简称「本服务」）就本服务用户（以下简称「用户」）的个人信息及用户所提供数据的处理，制定如下隐私政策（以下简称「本政策」）。","privacy.1t":"1. 收集的信息","privacy.1li1":"<span class='text-white'>账户信息</span>：通过 GitHub 集成登录时获取的用户名、电子邮件地址、公开资料等。","privacy.1li2":"<span class='text-white'>解析对象数据</span>：用户所连接的 GitHub 仓库的源代码及元数据（文件结构、提交历史、依赖关系等）。","privacy.1li3":"<span class='text-white'>使用数据</span>：测验作答与学习进度、操作日志、访问日志（IP 地址、浏览器信息、访问时间等）。","privacy.2t":"2. 使用目的","privacy.2li1":"本服务的提供与运营（理解度实测、代码解析、学习计划与测验的生成、代码改善建议等）。","privacy.2li2":"本服务的质量提升、功能改善及缺陷处理。","privacy.2li3":"防止滥用、确保安全及分析使用情况。","privacy.3t":"3. 与外部服务的集成","privacy.3p":"本服务为提供功能，会与以下外部服务集成。集成方对信息的处理遵循各服务的规定。","privacy.3li1":"<span class='text-white'>GitHub</span>：用于认证及仓库集成。","privacy.3li2":"<span class='text-white'>AI 解析平台（Google Vertex AI / Gemini 等）</span>：为进行代码解析与学习内容生成，会在必要范围内发送代码等。发送前会实施对个人信息（PII）及密钥的屏蔽。","privacy.4t":"4. 向第三方提供","privacy.4p":"除依据法律法规或存在其他正当理由的情形外，未经用户同意不会向第三方提供个人信息。","privacy.5t":"5. 经由组织账户的使用","privacy.5p":"当用户通过其所属组织（团队、企业等）使用本服务时，该组织的管理员可能可以访问成员的账户设置，以及解析结果、理解度、学习状况等数据。以组织为单位使用时的处理，还须遵循该组织的方针。","privacy.6t":"6. 存储与安全","privacy.6p":"所收集的信息将在采取加密、访问控制等适当的技术与组织措施的基础上，于云平台（Google Cloud）上进行管理。","privacy.7t":"7. 保留期限与删除","privacy.7p":"信息将在实现使用目的所需的期限内保留，期限届满后或应用户要求，将进行适当的删除或匿名化。随着账户的删除，相关数据也将被删除。","privacy.8t":"8. 跨境数据传输","privacy.8p":"本服务使用云平台（Google Cloud）及 AI 解析平台，用户的数据可能会在日本境外（美国等）的服务器上存储与处理。在此情形下，仍将依据适用的法律法规采取适当的保护措施。","privacy.9t":"9. 处理的法律依据（面向 EEA / 英国用户）","privacy.9p":"对于欧洲经济区（EEA）或英国的用户，本公司依据 GDPR 等，以 (1) 合同的履行、(2) 法律义务的遵守、(3) 正当利益（确保服务安全、改善等）、(4) 用户的同意 中的任一项作为法律依据处理个人数据。基于同意的处理，可随时撤回。","privacy.10t":"10. 用户的权利","privacy.10p":"用户可就自身的个人信息，要求披露、更正、删除、停止使用等。在提出请求时，为进行身份核实，我们可能会请您提供额外信息。根据您所在地区的法律法规（GDPR、CCPA 等），您可能被赋予数据可携权、对处理提出异议等额外权利。请与咨询窗口联系。","privacy.11t":"11. Cookie 的使用","privacy.11p":"本服务使用维持登录状态及确保安全所必需的 Cookie（必需 Cookie）。不使用以广告、追踪为目的的 Cookie。您可通过浏览器设置或 DNT / GPC 信号控制 Cookie，但如禁用必需 Cookie，部分功能可能将无法使用。","privacy.12t":"12. 本政策的修订","privacy.12p":"本政策可能会根据法律法规的变更或服务内容的变更而修订。如有重大变更，将在本服务上予以告知。","privacy.13t":"13. 咨询","privacy.13p":"有关本政策的咨询，请与本服务的运营者联系。","privacy.updated":"最后更新日期：2026 年 7 月 6 日"},"ko":{"nav.how":"구조","nav.features":"기능","nav.infra":"인프라","nav.security":"보안","nav.cta":"데모 체험하기","hero.sub":"코드베이스의 이해도를 실측하고 촉진하는 개발 플랫폼","hero.h1":"퀴즈로 <span class='text-know'>이해도</span>를 실측하고, <span class='text-know'>이해도 맵</span>으로 시각화. <br class='hidden sm:block' />저품질 코드를 <span class='text-code'>AI 자동 수정 PR</span>로 개선.","hero.lead":"AI 에이전트가 <strong class='font-semibold text-white'>서브 에이전트·MCP·Hook</strong>을 활용해 리포지토리를 다각도로 분석. <br class='hidden lg:block' />기능 추출부터 이해도 실측, 코드 품질 감지, 수정 제안까지 하나로 이어 자동화합니다.","hero.chip1":"AI 에이전트 × MCP로 고도화된 리포지토리 탐색","hero.chip2":"GitHub 연동으로 간편 로그인","hero.chip3":"PII·시크릿 자동 마스킹","hero.chip4":"모바일 대응","hero.chip5":"확장 가능한 인프라 구성","challenge.h2":"AI 시대에 빠르게 쌓여가는 '이해 부채'","challenge.lead":"Claude Code·Codex·Gemini CLI 등의 보급으로 '개발'과 '운영'의 사이클은 가속화되는 한편, 그 속도 속에서 <strong class='text-white'>코드를 '이해하는' 일이 뒷전으로 밀리고</strong>, AI가 생성한 코드가 무엇을 하는지·왜 그렇게 작성되었는지 설명하지 못하는 '이해 부채'가 빠르게 축적되고 있습니다.","challenge.c1t":"'돌아가면 그만'이라며 이해가 방치됨","challenge.c1d":"납기와 배포 속도가 우선되어 코드를 이해하는 단계가 생략된다. 작성한 사람 외에는 내용을 모른 채 진행된다.","challenge.c2t":"AI에 맡겨 사고가 건너뛰어짐","challenge.c2d":"그럴듯한 생성 코드를 그대로 신뢰하고, '왜 그렇게 작성하는가'를 묻지 않은 채 프로덕션으로. 이해되지 않은 코드가 계속 늘어난다.","challenge.c3t":"'이해하고 있는지'는 측정되지 않음","challenge.c3d":"리뷰나 테스트는 품질을 측정해도, 사람의 이해도는 측정하지 않는다. 어디부터 손대야 할지, 긴급도도 알 수 없다.","audience.h2":"이런 분께","audience.a1t":"테크 리드 / 매니저","audience.a1d":"팀원의 이해도가 낮은 부분을 파악하고, 리뷰나 학습의 우선순위를 정하고 싶다.","audience.a2t":"온보딩 담당자 / 신규 합류 멤버","audience.a2d":"어디부터 이해해야 할지를 학습 유닛과 퀴즈로 체계적으로 따라가고 싶다.","flow.h2":"개발·운영 사이클에 기술 부채·이해 부채 해소를 녹여내다","flow.sub":"분석부터 이해의 실측·품질 감지, 학습·개선까지 하나로 이어집니다. '실측 → 학습'과 '감지 → 개선'의 두 축으로 상환합니다.","flow.s0t":"리포지토리 분석","flow.s0d":"AI 에이전트가 MCP를 사용해 코드베이스를 횡단 탐색. 파일 그룹을 기능 단위로 클러스터링하고, 기술 스택과 의존 관계도 파악.","flow.track_know":"이해 부채","flow.track_code":"기술 부채","flow.s1t":"퀴즈 생성·실측","flow.s1d":"기능별로 이해도 퀴즈를 자동 생성. 응답에서 '누가 어디를 이해하고 있는지'를 파일 단위로 객관적으로 실측.","flow.s2t":"학습 플랜 생성","flow.s2d":"이해가 얕은 기능에 맞춰, 해당 코드의 워크스루나 기술 문서를 포함한 학습 플랜을 에이전트가 자동으로 구성.","flow.s3t":"저품질 코드 감지","flow.s3d":"중복·복잡도·데드 코드·AI 생성 흔적 등을 분석해, 품질이 낮고 우선순위가 높은 파일을 특정.","flow.s4t":"코드 개선 제안","flow.s4d":"저품질 코드에 대해 AI가 자동으로 수정 PR을 작성. 담당자를 할당한 Issue 발행에도 대응.","flow.s5t":"이해도·품질이 향상","flow.s5d":"'실측 → 학습'과 '감지 → 개선'의 두 축으로 속인화를 해소하고, 코드베이스의 이해도와 코드 품질을 지속적으로 향상.","core.h2":"3가지 핵심 기능","core.c1t":"AI 에이전트를 통한 고도화된 리포지토리 분석","core.c1d":"Google ADK로 구축한 에이전트가 MCP(Serena / CodeGraphContext / Semgrep / GitHub)를 구사해 리포지토리를 탐색. 기능별 학습 플랜·퀴즈 생성, 저품질 코드의 감지와 수정 계획 작성까지 자동화합니다.","core.c2t":"이해 부채의 시각화 × 퀴즈와 학습으로 개선","core.c2d":"소스 코드를 기능 단위로 클러스터링하고, 기능별로 학습 플랜과 이해도 확인 테스트를 생성. 그래프로 이해 부채를 시각화하고, 퀴즈 → 학습의 폐루프로 능동적으로 상환합니다.","core.c3t":"저품질 코드에 대한 권장 제안과 자동 수정","core.c3d":"분석으로 검출한 저품질 코드에 대해 권장 사항을 GitHub Issue로 발행. 담당자 할당이나 수정 PR의 자동 작성까지 수행할 수 있습니다.","core.oplabel":"실운영을 염두에 둔 기능","core.pill1":"GitHub SSO 인증·인가","core.pill2":"프로젝트 관리","core.pill3":"온보딩 가이드","core.pill4":"풍부한 단축키","core.pill5":"관리자에 의한 사용자 관리","core.pill6":"크레딧 부여를 통한 과금 제어","core.pill7":"i18n 다국어 대응","core.pill8":"릴리스 이력 확인","features.h2":"앱으로 할 수 있는 것","features.sub":"분석부터 대시보드, 시각화, 개선까지 하나의 워크스페이스에서.","features.f1t":"대시보드 — 전체 그림을 한눈에","features.f1lead":"리포지토리의 이해도와 코드 품질을 한 화면에서 확인할 수 있습니다.","features.f1li1":"・<strong class='text-white'>매트릭스</strong>는 파일을 '이해도 × 코드 품질'의 두 축으로 정리. 둘 다 낮은 파일이 우선적으로 개선해야 할 영역.","features.f1li2":"・<strong class='text-white'>지표</strong>는 이해도·저품질 파일 건수·수정 완료 건수를 변화량과 함께 표시.","features.f1li3":"・<strong class='text-white'>추이 그래프</strong>로 코드 품질과 이해도의 시간 변화를 확인.","features.f1li4":"・<strong class='text-white'>우선 대응 리스트</strong>로 대응해야 할 파일을 한눈에.","features.f1tag1":"이해도 × 품질의 두 축","features.f1tag2":"핫스팟 시각화","features.f1tag3":"우선 대응 스코어","features.f2t":"이해도 맵 — 누가 어디를 알고 있는가","features.f2lead":"기능·파일별로 사용자의 이해도를 그래프로 시각화합니다. 표시는 <strong class='font-semibold text-white'>맵</strong>과 <strong class='font-semibold text-white'>리스트</strong>의 2종류. <strong class='font-semibold text-white'>기능 칩</strong>으로 특정 기능과 관련된 파일 그룹만 좁힐 수 있습니다. 맵 표시는 노드＝파일, 선＝의존 관계, 색＝이해도로, 노드를 선택하면 인접 파일을 강조 표시.","features.f2leg1":"이해 완료","features.f2leg2":"부분 이해","features.f2leg3":"미이해","features.f2leg4":"미착수","features.f2tag1":"CodeGraphContext를 통한 그래프 시각화","features.f2tag2":"파일 간 의존 관계 분석","features.f2tag3":"기능 클러스터링","features.f3t":"코드 품질 맵 — 품질 분포를 조망","features.f3lead":"소스 코드를 파일 단위로 열람하고, 어떤 파일에 어떤 개선 여지가 있는지 확인할 수 있습니다.","features.f3li1":"・왼쪽의 <strong class='text-white'>파일 트리</strong>에서 파일을 선택. 개선 여지가 있는 파일에는 <strong class='text-white'>배지</strong>가 붙습니다.","features.f3li2":"・오른쪽에 선택한 파일의 내용을 표시. <strong class='text-white'>지적 부분이 하이라이트</strong>되어 그 자리에서 확인할 수 있습니다.","features.f3tag1":"Serena MCP(LSP)를 통한 분석","features.f3tag2":"Semgrep을 통한 정적 분석","features.f3tag3":"데드 코드 감지","features.f4t":"퀴즈와 학습 — 실측으로 이해를 심화","features.f4lead":"기능별 학습 플랜을 수강하고, 확인 퀴즈로 이해도를 체크합니다.","features.f4li1":"<strong class='text-white'>・학습 플랜 목록</strong> — 각 플랜의 상태와 이해도, 전체 학습 진행도를 확인. 복습하고 싶은 단원에는 플래그를 붙여 목록 상단에 모을 수 있습니다.","features.f4li2":"<strong class='text-white'>・학습 열기</strong> — 리포지토리 고유의 기능을 워크스루로 배우고, 관련 기술의 공식 문서도 참조. 중요한 처리를 단계적으로 이해.","features.f4li3":"<strong class='text-white'>・이해도 확인하기</strong> — 확인 퀴즈를 응시. 나중에 복습하고 싶은 문제에 플래그를 붙일 수 있고, 플래그／오답에 한정한 재테스트로 약점을 반복 복습할 수 있습니다.","features.f4tag1":"ADK 에이전트가 학습 플랜·퀴즈를 생성","features.f4tag2":"리포지토리 고유 × 기술 스택의 두 축으로 학습","features.f4tag3":"플래그·오답의 재테스트","features.f5t":"코드 개선 — PR / Issue로 되돌리다","features.f5lead":"파일 단위로 개선 부분을 확인하고, AI를 통한 수정 Pull Request의 자동 생성이나 Issue 작성이 가능합니다.","features.f5li1":"・<strong class='text-white'>필터</strong>로 좁히고, <strong class='text-white'>우선순위 순</strong>으로 정렬. 개선 대상을 클릭하면 상세 화면으로.","features.f5li2":"・상세 화면에서는 문제의 코드 부분이 하이라이트되어, <strong class='text-white'>품질이 낮은 이유·우선순위·추정 공수</strong>를 확인.","features.f5li3":"・개선 방법은 <strong class='text-white'>'AI에게 수정 PR을 자동 작성'</strong>이나 <strong class='text-white'>'담당자를 할당해 Issue를 작성'</strong> 중에서 선택.","features.f5tag1":"AI가 수정 패치를 생성","features.f5tag2":"수정 PR 자동 생성","features.f5tag3":"GitHub Issue 발행","infra.h2":"인프라 구성","infra.lead":"Cloud Tasks를 활용해 분석은 비동기 워커로 분리. 부하에 따라 Cloud Run이 자동 스케일. <br class='hidden sm:block' />분석은 ADK로 구축한 에이전트와 MCP의 활용을 통해, 망라적이고 효율적인 리포지토리 탐색을 실현. <br class='hidden sm:block' />Cloud Armor를 통한 레이트 제한·Secret Manager 및 Cloud DLP로 보안을 확보. 인프라는 Terraform으로 IaC화. <br class='hidden sm:block' />개발 시에는 CI/CD가 테스트부터 배포에 더해 린터/포매터의 자동 적용과 Gemini를 통한 자동 코드 리뷰까지 돌려, 코드 품질을 높게 유지합니다.","security.h2":"보안에서 중점을 두는 것","security.s1t":"인증·세션","security.s1d":"JWT 토큰을 사용한 GitHub SSO. 액세스 토큰과 리프레시 토큰을 사용한 안전한 세션 관리. 30분간 조작이 없을 때의 세션 타임아웃.","security.s2t":"동일 오리진 배포와 웹 취약점 대책","security.s2d":"UI와 API를 동일 오리진으로 배포함으로써 CORS 설정 불필요. 더불어 XSS·CSRF·SSRF 등 웹 애플리케이션에 필요한 대책을 실시.","security.s3t":"키를 갖지 않는 설계","security.s3d":"Workload Identity Federation으로 장기 크레덴셜을 배제. 배포 시의 시크릿은 GitHub Secrets로 주입하고, 실행 시에는 Secret Manager에 집약해 관리합니다.","security.s4t":"엣지 및 앱 내에서의 레이트 제한","security.s4d":"Cloud Armor로 앱 앞단에서 과도한 요청을 제한. 앱 내에서는 관리자가 리포지토리 분석의 크레딧을 부여·관리할 수 있어, 비용이 큰 분석 처리의 남용을 방지합니다.","security.s5t":"에이전트 입력의 마스킹","security.s5d":"에이전트에 정보를 제공할 때는, Cloud DLP(Sensitive Data Protection)와 detect-secrets로 PII·시크릿을 마스킹한 후 전송합니다.","security.s6t":"취약점 스캔","security.s6d":"OWASP에 준거한 애플리케이션의 취약점 스캔 및, Trivy를 사용한 컨테이너 이미지의 취약점 스캔을 실시.","mobile.h2":"스마트폰에서도, 언제든 이해도를 체크","mobile.sub":"반응형 대응으로, 스마트폰에서도 주요 기능을 그대로 이용 가능. <br class='hidden sm:block' />이동 중이나 리뷰 틈틈이에도 이해도 맵 확인·코드 품질 파악·퀴즈 응시가 가능합니다.","mobile.l1":"대시보드","mobile.l2":"이해도 맵","mobile.l3":"코드 품질 맵","mobile.l4":"퀴즈와 학습","mobile.l5":"코드 개선","stack.h2":"기술 스택","cta.h2":"팀의 이해도를, 오늘부터 가시화","cta.p":"GitHub 리포지토리를 연결해 분석하기만 하면 됩니다. 이해 부채와 기술 부채 어느 쪽에도 접근할 수 있고, 일상의 개발·운영(DevOps) 사이클에 그대로 녹여 넣을 수 있습니다.","cta.btn":"리포지토리를 연결하고 시작하기","footer.privacy":"개인정보 처리방침","privacy.title":"개인정보 처리방침","privacy.intro":"DevDebtOps(이하 '본 서비스'라 합니다)는, 본 서비스의 이용자(이하 '이용자'라 합니다)의 개인정보 및 이용자가 제공하는 데이터의 취급에 관하여, 다음과 같이 개인정보 처리방침(이하 '본 방침'이라 합니다)을 정합니다.","privacy.1t":"1. 취득하는 정보","privacy.1li1":"<span class='text-white'>계정 정보</span>：GitHub 연동을 통한 로그인 시 취득하는 사용자명·이메일 주소·공개 프로필 등.","privacy.1li2":"<span class='text-white'>분석 대상 데이터</span>：이용자가 연결한 GitHub 리포지토리의 소스 코드 및 메타데이터(파일 구성·커밋 이력·의존 관계 등).","privacy.1li3":"<span class='text-white'>이용 데이터</span>：퀴즈의 응답·학습 진행도, 조작 로그, 액세스 로그(IP 주소·브라우저 정보·액세스 일시 등).","privacy.2t":"2. 이용 목적","privacy.2li1":"본 서비스의 제공·운영(이해도의 실측, 코드 분석, 학습 플랜·퀴즈의 생성, 코드 개선 제안 등).","privacy.2li2":"본 서비스의 품질 향상, 기능 개선 및 결함에 대한 대응.","privacy.2li3":"부정 이용의 방지, 보안 확보 및 이용 상황의 분석.","privacy.3t":"3. 외부 서비스와의 연동","privacy.3p":"본 서비스는, 기능 제공을 위해 다음의 외부 서비스와 연동합니다. 연동처에서의 정보 취급은 각 서비스의 규정에 따릅니다.","privacy.3li1":"<span class='text-white'>GitHub</span>：인증 및 리포지토리 연동을 위해.","privacy.3li2":"<span class='text-white'>AI 분석 기반(Google Vertex AI / Gemini 등)</span>：코드 분석·학습 콘텐츠 생성을 위해, 필요한 범위에서 코드 등을 전송합니다. 전송 전에 개인정보(PII) 및 시크릿의 마스킹을 실시합니다.","privacy.4t":"4. 제3자 제공","privacy.4p":"법령에 근거하는 경우 그 밖의 정당한 이유가 있는 경우를 제외하고, 이용자의 동의 없이 개인정보를 제3자에게 제공하지 않습니다.","privacy.5t":"5. 조직 계정을 통한 이용","privacy.5p":"이용자가 소속된 조직(팀·기업 등)을 통해 본 서비스를 이용하는 경우, 해당 조직의 관리자는 멤버의 계정 설정이나, 분석 결과·이해도·학습 상황 등의 데이터에 액세스할 수 있는 경우가 있습니다. 조직 단위의 이용에서의 취급은, 해당 조직의 방침에도 따릅니다.","privacy.6t":"6. 보관과 보안","privacy.6p":"취득한 정보는, 암호화·액세스 제어 등 적절한 기술적·조직적 조치를 강구한 후, 클라우드 기반(Google Cloud)상에서 관리합니다.","privacy.7t":"7. 보유 기간과 삭제","privacy.7p":"정보는 이용 목적의 달성에 필요한 기간 보유하며, 기간 경과 후 또는 이용자의 요청에 따라, 적절하게 삭제 또는 익명화합니다. 계정의 삭제에 따라, 관련된 데이터는 삭제됩니다.","privacy.8t":"8. 국경 간 데이터 이전","privacy.8p":"본 서비스는 클라우드 기반(Google Cloud) 및 AI 분석 기반을 이용하고 있어, 이용자의 데이터가 일본 국외(미국 등)의 서버에서 보관·처리되는 경우가 있습니다. 이 경우에도, 적용되는 법령에 따라 적절한 보호 조치를 강구합니다.","privacy.9t":"9. 처리의 법적 근거(EEA / 영국 이용자용)","privacy.9p":"유럽 경제 지역(EEA) 또는 영국의 이용자에 대하여, 당사는 GDPR 등에 근거하여, (1) 계약의 이행, (2) 법적 의무의 준수, (3) 정당한 이익(서비스의 안전 확보·개선 등), (4) 이용자의 동의 중 어느 하나를 법적 근거로 하여 개인 데이터를 처리합니다. 동의에 근거한 처리는, 언제든지 철회할 수 있습니다.","privacy.10t":"10. 이용자의 권리","privacy.10p":"이용자는, 자신의 개인정보에 대하여, 공개·정정·삭제·이용 정지 등을 요구할 수 있습니다. 청구 시에는, 본인 확인을 위해 추가 정보의 제공을 요청하는 경우가 있습니다. 거주하시는 지역의 법령(GDPR·CCPA 등)에 따라, 데이터 이동성이나 처리에 대한 이의 등 추가적인 권리가 인정되는 경우가 있습니다. 문의 창구로 연락해 주십시오.","privacy.11t":"11. Cookie의 이용","privacy.11p":"본 서비스는, 로그인 상태의 유지 및 보안 확보에 필요한 Cookie(필수 Cookie)를 사용합니다. 광고·트래킹 목적의 Cookie는 사용하지 않습니다. 브라우저 설정이나 DNT / GPC 시그널로 Cookie를 제어할 수 있지만, 필수 Cookie를 비활성화하면 일부 기능을 이용할 수 없게 되는 경우가 있습니다.","privacy.12t":"12. 본 방침의 개정","privacy.12p":"본 방침은, 법령의 변경이나 서비스 내용의 변경에 따라 개정하는 경우가 있습니다. 중요한 변경이 있는 경우에는, 본 서비스상에서 공지합니다.","privacy.13t":"13. 문의","privacy.13p":"본 방침에 관한 문의는, 본 서비스의 운영자에게 연락해 주십시오.","privacy.updated":"최종 업데이트일：2026년 7월 6일"},"es":{"nav.how":"Cómo funciona","nav.features":"Funciones","nav.infra":"Infraestructura","nav.security":"Seguridad","nav.cta":"Probar la demo","hero.sub":"La plataforma de desarrollo que mide e impulsa la comprensión de tu código","hero.h1":"Mide la <span class='text-know'>comprensión</span> con cuestionarios y visualízala en un <span class='text-know'>mapa de comprensión</span>.<br class='hidden sm:block' />Mejora el código de baja calidad con <span class='text-code'>PR de corrección automática por IA</span>.","hero.lead":"Los agentes de IA aprovechan <strong class='font-semibold text-white'>subagentes, MCP y Hooks</strong> para analizar el repositorio desde múltiples ángulos.<br class='hidden lg:block' />Automatizan de principio a fin la extracción de funciones, la medición de la comprensión, la detección de la calidad del código y las propuestas de corrección.","hero.chip1":"Exploración avanzada del repositorio con agentes de IA × MCP","hero.chip2":"Inicio de sesión sencillo con integración de GitHub","hero.chip3":"Enmascaramiento automático de PII y secretos","hero.chip4":"Compatible con móviles","hero.chip5":"Arquitectura de infraestructura escalable","challenge.h2":"La «deuda de comprensión» que se acumula a toda velocidad en la era de la IA","challenge.lead":"Con la difusión de Claude Code, Codex, Gemini CLI y otros, el ciclo de «desarrollo» y «operación» se acelera, pero en medio de esa velocidad <strong class='text-white'>comprender el código queda relegado a un segundo plano</strong>, y se acumula rápidamente una «deuda de comprensión»: la incapacidad de explicar qué hace el código generado por la IA o por qué está escrito así.","challenge.c1t":"«Con que funcione basta»: la comprensión se queda atrás","challenge.c1d":"Se priorizan los plazos y la velocidad de despliegue, y se omite el paso de comprender el código. Se avanza sin que nadie salvo quien lo escribió entienda su contenido.","challenge.c2t":"Se delega en la IA y se salta el razonamiento","challenge.c2d":"Se confía tal cual en código generado que parece plausible y llega a producción sin preguntarse «por qué se escribe así». El código no comprendido sigue creciendo.","challenge.c3t":"«Si se comprende o no» no se mide","challenge.c3d":"Las revisiones y las pruebas miden la calidad, pero no la comprensión de las personas. No se sabe por dónde empezar ni cuál es la urgencia.","audience.h2":"Ideal para","audience.a1t":"Líderes técnicos / Managers","audience.a1d":"Quieren identificar dónde es baja la comprensión del equipo y priorizar las revisiones y el aprendizaje.","audience.a2t":"Responsables de onboarding / Nuevos integrantes","audience.a2d":"Quieren seguir de forma sistemática por dónde empezar a comprender, mediante unidades de aprendizaje y cuestionarios.","flow.h2":"Incorpora la resolución de la deuda técnica y la deuda de comprensión al ciclo de desarrollo y operación","flow.sub":"De extremo a extremo, desde el análisis hasta la medición de la comprensión, la detección de la calidad y el aprendizaje y la mejora. Se salda con los dos motores: «medir → aprender» y «detectar → mejorar».","flow.s0t":"Análisis del repositorio","flow.s0d":"Los agentes de IA usan MCP para explorar el código de forma transversal. Agrupan los archivos por funciones y captan también la pila tecnológica y las dependencias.","flow.track_know":"Deuda de comprensión","flow.track_code":"Deuda técnica","flow.s1t":"Generar cuestionarios y medir","flow.s1d":"Genera automáticamente cuestionarios de comprensión por cada función. A partir de las respuestas, mide de forma objetiva y por archivo «quién comprende qué».","flow.s2t":"Generar un plan de aprendizaje","flow.s2d":"Según las funciones peor comprendidas, el agente arma automáticamente un plan de aprendizaje que incluye recorridos por el código correspondiente y documentación técnica.","flow.s3t":"Detección de código de baja calidad","flow.s3d":"Analiza la duplicación, la complejidad, el código muerto y los rastros de generación por IA, e identifica los archivos de baja calidad y alta prioridad.","flow.s4t":"Proponer mejoras de código","flow.s4d":"La IA crea automáticamente PR de corrección para el código de baja calidad. También admite la apertura de Issues con responsables asignados.","flow.s5t":"Mejora de la comprensión y la calidad","flow.s5d":"Con los dos motores «medir → aprender» y «detectar → mejorar», elimina la dependencia de personas concretas y mejora de forma continua la comprensión y la calidad del código.","core.h2":"3 funciones principales","core.c1t":"Análisis avanzado del repositorio con agentes de IA","core.c1d":"Un agente construido con Google ADK explora el repositorio aprovechando MCP (Serena / CodeGraphContext / Semgrep / GitHub). Automatiza la generación de planes de aprendizaje y cuestionarios por función, así como la detección de código de baja calidad y la elaboración de planes de corrección.","core.c2t":"Visualización de la deuda de comprensión × mejora con cuestionarios y aprendizaje","core.c2d":"Agrupa el código fuente por funciones y genera un plan de aprendizaje y una prueba de comprensión para cada una. Visualiza la deuda de comprensión con gráficos y la salda de forma activa con el ciclo cerrado cuestionario → aprendizaje.","core.c3t":"Recomendaciones y corrección automática del código de baja calidad","core.c3d":"Para el código de baja calidad detectado en el análisis, abre las recomendaciones como GitHub Issue. Permite asignar responsables e incluso crear automáticamente PR de corrección.","core.oplabel":"Funciones pensadas para el uso real","core.pill1":"Autenticación y autorización con GitHub SSO","core.pill2":"Gestión de proyectos","core.pill3":"Guía de onboarding","core.pill4":"Abundantes atajos de teclado","core.pill5":"Gestión de usuarios por el administrador","core.pill6":"Control de facturación mediante asignación de créditos","core.pill7":"Soporte multilingüe i18n","core.pill8":"Consulta del historial de versiones","features.h2":"Lo que puede hacer la aplicación","features.sub":"Del análisis al Dashboard, la visualización y la mejora, todo en un solo espacio de trabajo.","features.f1t":"Dashboard — la visión general de un vistazo","features.f1lead":"Consulta en una sola pantalla la comprensión y la calidad del código del repositorio.","features.f1li1":"・La <strong class='text-white'>matriz</strong> organiza los archivos en dos ejes: «comprensión × calidad del código». Los archivos bajos en ambos son las áreas que hay que mejorar con prioridad.","features.f1li2":"・Los <strong class='text-white'>indicadores</strong> muestran la comprensión, el número de archivos de baja calidad y el número de correcciones realizadas, con su variación.","features.f1li3":"・El <strong class='text-white'>gráfico de evolución</strong> muestra los cambios en el tiempo de la calidad del código y la comprensión.","features.f1li4":"・La <strong class='text-white'>lista de prioridades</strong> reúne los archivos que hay que atender.","features.f1tag1":"Dos ejes: comprensión × calidad","features.f1tag2":"Visualización de hotspots","features.f1tag3":"Puntuación de prioridad","features.f2t":"Mapa de comprensión — quién entiende qué","features.f2lead":"Visualiza con gráficos la comprensión de cada usuario por función y por archivo. Hay 2 vistas: <strong class='font-semibold text-white'>mapa</strong> y <strong class='font-semibold text-white'>lista</strong>. Con los <strong class='font-semibold text-white'>chips de función</strong> puedes filtrar solo los archivos relacionados con una función concreta. En la vista de mapa, nodo = archivo, línea = dependencia, color = comprensión, y al seleccionar un nodo se resaltan los archivos adyacentes.","features.f2leg1":"Comprendido","features.f2leg2":"Comprensión parcial","features.f2leg3":"Sin comprender","features.f2leg4":"Sin empezar","features.f2tag1":"Visualización de grafos con CodeGraphContext","features.f2tag2":"Análisis de dependencias entre archivos","features.f2tag3":"Agrupación por funciones","features.f3t":"Mapa de calidad del código — una panorámica de la distribución de la calidad","features.f3lead":"Consulta el código fuente archivo por archivo y comprueba qué archivos tienen qué margen de mejora.","features.f3li1":"・Selecciona un archivo en el <strong class='text-white'>árbol de archivos</strong> de la izquierda. Los archivos con margen de mejora llevan una <strong class='text-white'>insignia</strong>.","features.f3li2":"・A la derecha se muestra el contenido del archivo seleccionado. Los <strong class='text-white'>puntos señalados aparecen resaltados</strong> y puedes revisarlos ahí mismo.","features.f3tag1":"Análisis con Serena MCP (LSP)","features.f3tag2":"Análisis estático con Semgrep","features.f3tag3":"Detección de código muerto","features.f4t":"Cuestionarios y aprendizaje — mide y profundiza la comprensión","features.f4lead":"Sigue el plan de aprendizaje de cada función y comprueba tu comprensión con cuestionarios de repaso.","features.f4li1":"<strong class='text-white'>・Lista de planes de aprendizaje</strong> — consulta el estado y la comprensión de cada plan y el progreso global del aprendizaje. Marca las unidades que quieras repasar y se agruparán en la parte superior de la lista.","features.f4li2":"<strong class='text-white'>・Abrir el aprendizaje</strong> — aprende con recorridos las funciones propias del repositorio y consulta también la documentación oficial de las tecnologías relacionadas. Comprende paso a paso los procesos importantes.","features.f4li3":"<strong class='text-white'>・Comprobar la comprensión</strong> — realiza el cuestionario de repaso. Puedes marcar las preguntas que quieras repasar más tarde y repetir el repaso de tus puntos débiles con re-tests limitados a las preguntas marcadas o falladas.","features.f4tag1":"El agente ADK genera planes de aprendizaje y cuestionarios","features.f4tag2":"Aprendizaje con los dos motores: lo propio del repositorio × la pila tecnológica","features.f4tag3":"Marcado y re-test de respuestas falladas","features.f5t":"Mejora del código — devuelve con PR / Issue","features.f5lead":"Revisa los puntos de mejora archivo por archivo y genera automáticamente Pull Request de corrección por IA o crea Issues.","features.f5li1":"・Filtra con los <strong class='text-white'>filtros</strong> y ordena <strong class='text-white'>por prioridad</strong>. Haz clic en un elemento a mejorar para ir a la pantalla de detalle.","features.f5li2":"・En la pantalla de detalle se resalta el fragmento de código problemático y se muestran el <strong class='text-white'>motivo de la baja calidad, la prioridad y el esfuerzo estimado</strong>.","features.f5li3":"・Elige el método de mejora entre <strong class='text-white'>«Que la IA cree automáticamente un PR de corrección»</strong> o <strong class='text-white'>«Asignar un responsable y crear un Issue»</strong>.","features.f5tag1":"La IA genera el parche de corrección","features.f5tag2":"Generación automática de PR de corrección","features.f5tag3":"Apertura de GitHub Issue","infra.h2":"Arquitectura de infraestructura","infra.lead":"Aprovecha Cloud Tasks para separar el análisis en workers asíncronos. Cloud Run escala automáticamente según la carga.<br class='hidden sm:block' />El análisis logra una exploración exhaustiva y eficiente del repositorio gracias a los agentes construidos con ADK y al uso de MCP.<br class='hidden sm:block' />La seguridad se garantiza con la limitación de tasa de Cloud Armor y con Secret Manager y Cloud DLP. La infraestructura se define como IaC con Terraform.<br class='hidden sm:block' />Durante el desarrollo, el CI/CD no solo cubre desde las pruebas hasta el despliegue, sino que también aplica automáticamente linters y formateadores y ejecuta la revisión automática de código con Gemini, manteniendo alta la calidad del código.","security.h2":"En qué ponemos especial cuidado en materia de seguridad","security.s1t":"Autenticación y sesión","security.s1d":"GitHub SSO mediante tokens JWT. Gestión segura de la sesión con tokens de acceso y de refresco. Tiempo de espera de sesión tras 30 minutos sin actividad.","security.s2t":"Servicio en el mismo origen y protección frente a vulnerabilidades web","security.s2d":"Al servir la UI y la API desde el mismo origen no hace falta configurar CORS. Además, se aplican las medidas necesarias en aplicaciones web frente a XSS, CSRF, SSRF, etc.","security.s3t":"Diseño sin claves","security.s3d":"Workload Identity Federation elimina las credenciales de larga duración. Los secretos del despliegue se inyectan con GitHub Secrets y, en tiempo de ejecución, se centralizan y gestionan en Secret Manager.","security.s4t":"Limitación de tasa en el borde y dentro de la aplicación","security.s4d":"Cloud Armor limita las solicitudes excesivas antes de llegar a la aplicación. Dentro de la aplicación, el administrador puede asignar y gestionar créditos para el análisis del repositorio, evitando el abuso de procesos de análisis costosos.","security.s5t":"Enmascaramiento de la entrada del agente","security.s5d":"Al proporcionar información al agente, se enmascaran las PII y los secretos con Cloud DLP (Sensitive Data Protection) y detect-secrets antes de enviarlos.","security.s6t":"Escaneo de vulnerabilidades","security.s6d":"Se realiza el escaneo de vulnerabilidades de la aplicación conforme a OWASP, así como el escaneo de vulnerabilidades de las imágenes de contenedor con Trivy.","mobile.h2":"Comprueba tu comprensión en cualquier momento, también desde el móvil","mobile.sub":"Gracias al diseño responsive, las funciones principales se pueden usar tal cual desde el smartphone.<br class='hidden sm:block' />Incluso mientras te desplazas o entre revisiones, puedes consultar el mapa de comprensión, captar la calidad del código y realizar cuestionarios.","mobile.l1":"Dashboard","mobile.l2":"Mapa de comprensión","mobile.l3":"Mapa de calidad del código","mobile.l4":"Cuestionarios y aprendizaje","mobile.l5":"Mejora del código","stack.h2":"Pila tecnológica","cta.h2":"Haz visible la comprensión de tu equipo desde hoy mismo","cta.p":"Solo tienes que conectar y analizar tu repositorio de GitHub. Puedes abordar tanto la deuda de comprensión como la deuda técnica e integrarlo directamente en el ciclo diario de desarrollo y operación (DevOps).","cta.btn":"Conectar el repositorio y empezar","footer.privacy":"Política de privacidad","privacy.title":"Política de privacidad","privacy.intro":"DevDebtOps (en adelante, «el Servicio») establece la presente política de privacidad (en adelante, «esta Política») sobre el tratamiento de los datos personales de los usuarios del Servicio (en adelante, «el Usuario») y de los datos que el Usuario proporciona, en los términos que se indican a continuación.","privacy.1t":"1. Información que recopilamos","privacy.1li1":"<span class='text-white'>Información de la cuenta</span>: nombre de usuario, dirección de correo electrónico, perfil público, etc., obtenidos al iniciar sesión mediante la integración con GitHub.","privacy.1li2":"<span class='text-white'>Datos objeto de análisis</span>: el código fuente y los metadatos (estructura de archivos, historial de commits, dependencias, etc.) de los repositorios de GitHub que el Usuario conecta.","privacy.1li3":"<span class='text-white'>Datos de uso</span>: respuestas a los cuestionarios y progreso del aprendizaje, registros de operaciones y registros de acceso (dirección IP, información del navegador, fecha y hora de acceso, etc.).","privacy.2t":"2. Finalidades de uso","privacy.2li1":"Prestación y operación del Servicio (medición de la comprensión, análisis de código, generación de planes de aprendizaje y cuestionarios, propuestas de mejora de código, etc.).","privacy.2li2":"Mejora de la calidad del Servicio, mejora de funciones y resolución de fallos.","privacy.2li3":"Prevención del uso indebido, garantía de la seguridad y análisis del uso.","privacy.3t":"3. Integración con servicios externos","privacy.3p":"Para la prestación de sus funciones, el Servicio se integra con los siguientes servicios externos. El tratamiento de la información en los destinos de integración se rige por lo establecido por cada servicio.","privacy.3li1":"<span class='text-white'>GitHub</span>: para la autenticación y la integración del repositorio.","privacy.3li2":"<span class='text-white'>Infraestructura de análisis por IA (Google Vertex AI / Gemini, etc.)</span>: para el análisis de código y la generación de contenidos de aprendizaje, se envía el código, etc., en la medida necesaria. Antes del envío se enmascaran los datos personales (PII) y los secretos.","privacy.4t":"4. Cesión a terceros","privacy.4p":"Salvo cuando lo exija la ley u otras causas justificadas, no cedemos datos personales a terceros sin el consentimiento del Usuario.","privacy.5t":"5. Uso a través de una cuenta de organización","privacy.5p":"Cuando el Usuario utiliza el Servicio a través de la organización a la que pertenece (equipo, empresa, etc.), el administrador de dicha organización puede acceder a la configuración de la cuenta de los miembros y a datos como los resultados del análisis, la comprensión y el estado del aprendizaje. El tratamiento en el uso a nivel de organización se rige también por las políticas de dicha organización.","privacy.6t":"6. Almacenamiento y seguridad","privacy.6p":"La información obtenida se gestiona en una infraestructura en la nube (Google Cloud), aplicando medidas técnicas y organizativas adecuadas como el cifrado y el control de acceso.","privacy.7t":"7. Periodo de conservación y eliminación","privacy.7p":"La información se conserva durante el periodo necesario para cumplir las finalidades de uso y, transcurrido dicho periodo o a petición del Usuario, se elimina o anonimiza de forma adecuada. Con la eliminación de la cuenta se eliminan los datos relacionados.","privacy.8t":"8. Transferencia internacional de datos","privacy.8p":"El Servicio utiliza una infraestructura en la nube (Google Cloud) y una infraestructura de análisis por IA, por lo que los datos del Usuario pueden almacenarse y procesarse en servidores fuera de Japón (por ejemplo, en Estados Unidos). También en ese caso se aplican las medidas de protección adecuadas conforme a la legislación aplicable.","privacy.9t":"9. Base jurídica del tratamiento (para usuarios del EEA / Reino Unido)","privacy.9p":"Respecto a los usuarios del Espacio Económico Europeo (EEA) o del Reino Unido, tratamos los datos personales sobre la base jurídica, conforme al GDPR y demás normativa, de: (1) la ejecución de un contrato, (2) el cumplimiento de obligaciones legales, (3) intereses legítimos (garantía de la seguridad del servicio, mejoras, etc.) o (4) el consentimiento del Usuario. El tratamiento basado en el consentimiento puede retirarse en cualquier momento.","privacy.10t":"10. Derechos del Usuario","privacy.10p":"El Usuario puede solicitar el acceso, la rectificación, la eliminación, la suspensión del uso, etc., de sus datos personales. Para la solicitud, es posible que le pidamos información adicional para verificar su identidad. Según la legislación de su región (GDPR, CCPA, etc.), pueden reconocerse derechos adicionales como la portabilidad de los datos o la oposición al tratamiento. Póngase en contacto con nuestro canal de atención.","privacy.11t":"11. Uso de cookies","privacy.11p":"El Servicio utiliza las cookies necesarias para mantener la sesión iniciada y garantizar la seguridad (cookies esenciales). No utiliza cookies con fines publicitarios ni de seguimiento. Puede controlar las cookies mediante la configuración del navegador o las señales DNT / GPC, pero si desactiva las cookies esenciales es posible que algunas funciones dejen de estar disponibles.","privacy.12t":"12. Modificación de esta Política","privacy.12p":"Esta Política puede modificarse en función de cambios en la legislación o en el contenido del Servicio. Cuando haya cambios importantes, se comunicarán en el Servicio.","privacy.13t":"13. Contacto","privacy.13p":"Para consultas relativas a esta Política, póngase en contacto con el operador del Servicio.","privacy.updated":"Última actualización: 6 de julio de 2026"},"de":{"nav.how":"Funktionsweise","nav.features":"Funktionen","nav.infra":"Infrastruktur","nav.security":"Sicherheit","nav.cta":"Demo ausprobieren","hero.sub":"Die Entwicklungsplattform, die das Codebasis-Verständnis misst und fördert","hero.h1":"Messe das <span class='text-know'>Verständnis</span> per Quiz und visualisiere es mit der <span class='text-know'>Verständniskarte</span>.<br class='hidden sm:block' />Verbessere Code von geringer Qualität mit <span class='text-code'>automatischen KI-Korrektur-PRs</span>.","hero.lead":"Ein KI-Agent nutzt <strong class='font-semibold text-white'>Subagenten, MCP und Hooks</strong>, um das Repository aus vielen Blickwinkeln zu analysieren.<br class='hidden lg:block' />Von der Extraktion der Funktionen über die Messung des Verständnisses und die Erkennung der Codequalität bis hin zu Korrekturvorschlägen wird alles durchgängig automatisiert.","hero.chip1":"Fortgeschrittene Repository-Erkundung mit KI-Agent × MCP","hero.chip2":"Einfache Anmeldung über GitHub-Integration","hero.chip3":"Automatisches Maskieren von PII und Secrets","hero.chip4":"Mobil optimiert","hero.chip5":"Skalierbare Infrastruktur","challenge.h2":"„Verständnisschulden“, die sich im KI-Zeitalter rasant aufbauen","challenge.lead":"Mit der Verbreitung von Claude Code, Codex, Gemini CLI und Co. beschleunigt sich der Zyklus aus „Entwicklung“ und „Betrieb“ immer weiter. In dieser Geschwindigkeit wird das <strong class='text-white'>„Verstehen“ von Code hintangestellt</strong>, und es häufen sich rasant „Verständnisschulden“ an – man kann nicht mehr erklären, was von KI generierter Code tut oder warum er so geschrieben ist.","challenge.c1t":"„Hauptsache es läuft“ – das Verständnis bleibt auf der Strecke","challenge.c1d":"Termine und Deployment-Geschwindigkeit haben Vorrang, der Schritt des Verstehens von Code wird übersprungen. Es geht weiter, ohne dass jemand außer dem Autor den Inhalt kennt.","challenge.c2t":"Denken wird der KI überlassen und übersprungen","challenge.c2d":"Plausibel wirkender generierter Code wird unverändert vertraut und ohne die Frage „Warum wird das so geschrieben?“ in Produktion gebracht. Nicht verstandener Code nimmt immer weiter zu.","challenge.c3t":"„Ob man es verstanden hat“ wird nicht gemessen","challenge.c3d":"Reviews und Tests messen die Qualität, aber nicht das Verständnis der Menschen. Wo man ansetzen soll und wie dringend es ist, bleibt unklar.","audience.h2":"Für wen sich das eignet","audience.a1t":"Tech-Lead / Manager","audience.a1d":"Erfassen, an welchen Stellen das Verständnis der Teammitglieder gering ist, und die Prioritäten für Reviews und Lernen festlegen.","audience.a2t":"Onboarding-Verantwortliche / neu hinzugekommene Mitglieder","audience.a2d":"Mit Lerneinheiten und Quizzen systematisch verfolgen, wo man mit dem Verstehen beginnen sollte.","flow.h2":"Den Abbau von technischen Schulden und Verständnisschulden in den Entwicklungs- und Betriebszyklus integrieren","flow.sub":"Von der Analyse über die Messung des Verständnisses und die Erkennung der Qualität bis hin zu Lernen und Verbesserung – alles durchgängig. Die Rückzahlung erfolgt über die beiden Achsen „Messen → Lernen“ und „Erkennen → Verbessern“.","flow.s0t":"Repository-Analyse","flow.s0d":"Der KI-Agent durchsucht die Codebasis mithilfe von MCP übergreifend. Er clustert Dateien nach Funktionseinheiten und erfasst auch den Technologie-Stack sowie Abhängigkeiten.","flow.track_know":"Verständnisschulden","flow.track_code":"Technische Schulden","flow.s1t":"Quiz generieren und messen","flow.s1d":"Für jede Funktion wird automatisch ein Verständnis-Quiz generiert. Aus den Antworten wird auf Dateiebene objektiv gemessen, „wer welche Stellen versteht“.","flow.s2t":"Lernplan generieren","flow.s2d":"Passend zu Funktionen mit geringem Verständnis stellt der Agent automatisch einen Lernplan zusammen, der Walkthroughs des betreffenden Codes und technische Dokumentation umfasst.","flow.s3t":"Erkennung von Code geringer Qualität","flow.s3d":"Duplikate, Komplexität, toter Code, Spuren von KI-Generierung und mehr werden analysiert, um Dateien mit niedriger Qualität und hoher Priorität zu identifizieren.","flow.s4t":"Codeverbesserung vorschlagen","flow.s4d":"Für Code geringer Qualität erstellt die KI automatisch Korrektur-PRs. Auch das Anlegen von Issues mit zugewiesenen Verantwortlichen wird unterstützt.","flow.s5t":"Verständnis und Qualität steigen","flow.s5d":"Über die beiden Achsen „Messen → Lernen“ und „Erkennen → Verbessern“ wird die Abhängigkeit von Einzelpersonen aufgelöst und das Verständnis der Codebasis sowie die Codequalität kontinuierlich verbessert.","core.h2":"Drei Kernfunktionen","core.c1t":"Fortgeschrittene Repository-Analyse durch KI-Agenten","core.c1d":"Ein mit Google ADK erstellter Agent durchsucht das Repository unter Einsatz von MCP (Serena / CodeGraphContext / Semgrep / GitHub). Von der Generierung von Lernplänen und Quizzen pro Funktion bis zur Erkennung von Code geringer Qualität und der Erstellung von Korrekturplänen wird alles automatisiert.","core.c2t":"Verständnisschulden visualisieren × mit Quiz und Lernen verbessern","core.c2d":"Der Quellcode wird nach Funktionseinheiten geclustert, und für jede Funktion werden ein Lernplan und ein Verständnistest generiert. Verständnisschulden werden in einem Graphen visualisiert und im geschlossenen Kreislauf aus Quiz → Lernen aktiv zurückgezahlt.","core.c3t":"Empfehlungen und automatische Korrektur für Code geringer Qualität","core.c3d":"Für in der Analyse erkannten Code geringer Qualität werden Empfehlungen als GitHub Issue angelegt. Die Zuweisung von Verantwortlichen sowie die automatische Erstellung von Korrektur-PRs sind ebenfalls möglich.","core.oplabel":"Auf den produktiven Einsatz ausgerichtete Funktionen","core.pill1":"GitHub SSO Authentifizierung und Autorisierung","core.pill2":"Projektverwaltung","core.pill3":"Onboarding-Leitfaden","core.pill4":"Umfangreiche Tastenkürzel","core.pill5":"Benutzerverwaltung durch Administratoren","core.pill6":"Abrechnungssteuerung über Credits","core.pill7":"i18n Mehrsprachigkeit","core.pill8":"Einsicht in den Versionsverlauf","features.h2":"Was die App kann","features.sub":"Von der Analyse über Dashboard, Visualisierung bis zur Verbesserung – alles in einem einzigen Workspace.","features.f1t":"Dashboard – das Gesamtbild auf einen Blick","features.f1lead":"Verständnis und Codequalität des Repositories lassen sich auf einer Seite überblicken.","features.f1li1":"・Die <strong class='text-white'>Matrix</strong> ordnet Dateien nach den beiden Achsen „Verständnis × Codequalität“. Dateien, die bei beiden niedrig liegen, sind der Bereich, der vorrangig verbessert werden sollte.","features.f1li2":"・Die <strong class='text-white'>Kennzahlen</strong> zeigen Verständnis, Anzahl der Dateien geringer Qualität und Anzahl der behobenen Dateien jeweils mit Veränderungswert.","features.f1li3":"・Mit dem <strong class='text-white'>Verlaufsdiagramm</strong> lässt sich die zeitliche Veränderung von Codequalität und Verständnis nachvollziehen.","features.f1li4":"・Die <strong class='text-white'>Prioritätenliste</strong> zeigt die Dateien, um die man sich kümmern sollte, in einer Übersicht.","features.f1tag1":"Zwei Achsen: Verständnis × Qualität","features.f1tag2":"Hotspot-Visualisierung","features.f1tag3":"Prioritäts-Score","features.f2t":"Verständniskarte – wer welche Stellen versteht","features.f2lead":"Nach Funktion und Datei wird das Verständnis der Nutzer in einem Graphen visualisiert. Es gibt zwei Darstellungen: <strong class='font-semibold text-white'>Karte</strong> und <strong class='font-semibold text-white'>Liste</strong>. Mit <strong class='font-semibold text-white'>Funktions-Chips</strong> lässt sich auf die Dateien einer bestimmten Funktion eingrenzen. In der Kartenansicht steht Knoten = Datei, Linie = Abhängigkeit, Farbe = Verständnis; wählt man einen Knoten aus, werden benachbarte Dateien hervorgehoben.","features.f2leg1":"Verstanden","features.f2leg2":"Teilweise verstanden","features.f2leg3":"Nicht verstanden","features.f2leg4":"Noch nicht begonnen","features.f2tag1":"Graph-Visualisierung mit CodeGraphContext","features.f2tag2":"Analyse der Abhängigkeiten zwischen Dateien","features.f2tag3":"Funktions-Clustering","features.f3t":"Codequalitätskarte – die Qualitätsverteilung im Überblick","features.f3lead":"Der Quellcode lässt sich dateiweise durchsehen, und man kann erkennen, welche Datei welches Verbesserungspotenzial hat.","features.f3li1":"・Wähle links im <strong class='text-white'>Dateibaum</strong> eine Datei aus. Dateien mit Verbesserungspotenzial erhalten ein <strong class='text-white'>Badge</strong>.","features.f3li2":"・Rechts wird der Inhalt der gewählten Datei angezeigt. Die <strong class='text-white'>beanstandeten Stellen sind hervorgehoben</strong> und lassen sich direkt prüfen.","features.f3tag1":"Analyse mit Serena MCP (LSP)","features.f3tag2":"Statische Analyse mit Semgrep","features.f3tag3":"Erkennung von totem Code","features.f4t":"Quiz und Lernen – messen und das Verständnis vertiefen","features.f4lead":"Absolviere den Lernplan pro Funktion und prüfe dein Verständnis mit einem Verständnis-Quiz.","features.f4li1":"<strong class='text-white'>・Übersicht der Lernpläne</strong> – Status und Verständnis jedes Plans sowie den gesamten Lernfortschritt einsehen. Einheiten, die man wiederholen möchte, lassen sich markieren und werden oben in der Übersicht zusammengefasst.","features.f4li2":"<strong class='text-white'>・Lernen öffnen</strong> – repository-spezifische Funktionen im Walkthrough lernen und auch die offizielle Dokumentation zugehöriger Technologien heranziehen. Wichtige Abläufe schrittweise verstehen.","features.f4li3":"<strong class='text-white'>・Verständnis prüfen</strong> – ein Verständnis-Quiz absolvieren. Fragen, die man später wiederholen möchte, lassen sich markieren, und mit einem auf markierte / falsch beantwortete Fragen beschränkten Wiederholungstest kann man Schwachstellen wiederholt üben.","features.f4tag1":"ADK-Agent generiert Lernpläne und Quizze","features.f4tag2":"Lernen über beide Achsen: repository-spezifisch × Technologie-Stack","features.f4tag3":"Markieren und Wiederholungstest falscher Antworten","features.f5t":"Codeverbesserung – als PR / Issue zurückgeben","features.f5lead":"Prüfe Verbesserungsstellen dateiweise und lass automatisch Korrektur-Pull-Requests durch die KI erstellen oder lege Issues an.","features.f5li1":"・Mit <strong class='text-white'>Filtern</strong> eingrenzen und <strong class='text-white'>nach Priorität</strong> sortieren. Klick auf ein Verbesserungsziel führt zur Detailansicht.","features.f5li2":"・In der Detailansicht ist die problematische Codestelle hervorgehoben, und man kann <strong class='text-white'>Grund für die geringe Qualität, Priorität und geschätzten Aufwand</strong> einsehen.","features.f5li3":"・Als Verbesserungsmethode wählt man zwischen <strong class='text-white'>„Korrektur-PR automatisch durch die KI erstellen“</strong> und <strong class='text-white'>„Verantwortlichen zuweisen und Issue erstellen“</strong>.","features.f5tag1":"KI generiert Korrektur-Patch","features.f5tag2":"Automatische Erstellung von Korrektur-PRs","features.f5tag3":"Anlegen von GitHub Issue","infra.h2":"Infrastruktur","infra.lead":"Mithilfe von Cloud Tasks wird die Analyse in asynchrone Worker ausgelagert. Je nach Last skaliert Cloud Run automatisch.<br class='hidden sm:block' />Durch den Einsatz von mit ADK erstellten Agenten und MCP erreicht die Analyse eine umfassende und effiziente Repository-Erkundung.<br class='hidden sm:block' />Ratenbegrenzung durch Cloud Armor sowie Secret Manager und Cloud DLP gewährleisten die Sicherheit. Die Infrastruktur wird mit Terraform als IaC umgesetzt.<br class='hidden sm:block' />Bei der Entwicklung durchläuft CI/CD neben Test bis Deployment auch die automatische Anwendung von Linter/Formatter sowie automatische Code-Reviews durch Gemini und hält so die Codequalität hoch.","security.h2":"Worauf wir bei der Sicherheit Wert legen","security.s1t":"Authentifizierung und Sitzung","security.s1d":"GitHub SSO mit JWT-Tokens. Sichere Sitzungsverwaltung mit Access- und Refresh-Token. Sitzungs-Timeout nach 30 Minuten ohne Aktivität.","security.s2t":"Same-Origin-Auslieferung und Schutz vor Web-Schwachstellen","security.s2d":"Durch die Auslieferung von UI und API über dieselbe Origin ist keine CORS-Konfiguration nötig. Zusätzlich werden die für Web-Anwendungen erforderlichen Schutzmaßnahmen gegen XSS, CSRF, SSRF usw. umgesetzt.","security.s3t":"Design ohne Schlüsselbesitz","security.s3d":"Mit Workload Identity Federation werden langlebige Credentials eliminiert. Secrets beim Deployment werden über GitHub Secrets injiziert, und zur Laufzeit werden sie im Secret Manager zentral verwaltet.","security.s4t":"Ratenbegrenzung an der Edge und in der App","security.s4d":"Cloud Armor begrenzt übermäßige Anfragen vor der App. Innerhalb der App können Administratoren Credits für die Repository-Analyse vergeben und verwalten und so den Missbrauch kostenintensiver Analyseprozesse verhindern.","security.s5t":"Maskierung von Agenten-Eingaben","security.s5d":"Bevor dem Agenten Informationen übergeben werden, werden PII und Secrets mit Cloud DLP (Sensitive Data Protection) und detect-secrets maskiert und erst dann gesendet.","security.s6t":"Schwachstellen-Scan","security.s6d":"Es werden ein OWASP-konformer Schwachstellen-Scan der Anwendung sowie ein Schwachstellen-Scan der Container-Images mit Trivy durchgeführt.","mobile.h2":"Auch am Smartphone jederzeit das Verständnis prüfen","mobile.sub":"Dank responsivem Design lassen sich die wichtigsten Funktionen auch vom Smartphone aus unverändert nutzen.<br class='hidden sm:block' />Ob unterwegs oder zwischen zwei Reviews – die Verständniskarte prüfen, die Codequalität erfassen und Quizze absolvieren ist überall möglich.","mobile.l1":"Dashboard","mobile.l2":"Verständniskarte","mobile.l3":"Codequalitätskarte","mobile.l4":"Quiz und Lernen","mobile.l5":"Codeverbesserung","stack.h2":"Technologie-Stack","cta.h2":"Mach das Verständnis deines Teams ab heute sichtbar","cta.p":"Einfach das GitHub-Repository verbinden und analysieren. Man kann sowohl Verständnisschulden als auch technische Schulden angehen und es unverändert in den täglichen Entwicklungs- und Betriebszyklus (DevOps) einbinden.","cta.btn":"Repository verbinden und starten","footer.privacy":"Datenschutzrichtlinie","privacy.title":"Datenschutzrichtlinie","privacy.intro":"DevDebtOps (nachfolgend „der Dienst“) legt hinsichtlich des Umgangs mit personenbezogenen Daten der Nutzer des Dienstes (nachfolgend „Nutzer“) sowie der von Nutzern bereitgestellten Daten die folgende Datenschutzrichtlinie (nachfolgend „diese Richtlinie“) fest.","privacy.1t":"1. Erhobene Informationen","privacy.1li1":"<span class='text-white'>Kontoinformationen</span>: Bei der Anmeldung über die GitHub-Integration erhobene Angaben wie Benutzername, E-Mail-Adresse und öffentliches Profil.","privacy.1li2":"<span class='text-white'>Analysedaten</span>: Quellcode und Metadaten (Dateistruktur, Commit-Historie, Abhängigkeiten usw.) der vom Nutzer verbundenen GitHub-Repositories.","privacy.1li3":"<span class='text-white'>Nutzungsdaten</span>: Quiz-Antworten und Lernfortschritt, Bedienungsprotokolle, Zugriffsprotokolle (IP-Adresse, Browser-Informationen, Zugriffszeitpunkt usw.).","privacy.2t":"2. Verwendungszwecke","privacy.2li1":"Bereitstellung und Betrieb des Dienstes (Messung des Verständnisses, Codeanalyse, Generierung von Lernplänen und Quizzen, Codeverbesserungsvorschläge usw.).","privacy.2li2":"Qualitätssteigerung des Dienstes, Funktionsverbesserung und Behebung von Fehlern.","privacy.2li3":"Verhinderung von Missbrauch, Gewährleistung der Sicherheit und Analyse der Nutzung.","privacy.3t":"3. Integration mit externen Diensten","privacy.3p":"Der Dienst arbeitet zur Bereitstellung von Funktionen mit den folgenden externen Diensten zusammen. Der Umgang mit Informationen bei den Partnern richtet sich nach den Bestimmungen des jeweiligen Dienstes.","privacy.3li1":"<span class='text-white'>GitHub</span>: für Authentifizierung und Repository-Integration.","privacy.3li2":"<span class='text-white'>KI-Analyseplattform (Google Vertex AI / Gemini usw.)</span>: Zur Codeanalyse und Generierung von Lerninhalten wird Code o. Ä. im erforderlichen Umfang übermittelt. Vor der Übermittlung werden personenbezogene Daten (PII) und Secrets maskiert.","privacy.4t":"4. Weitergabe an Dritte","privacy.4p":"Außer in gesetzlich vorgeschriebenen Fällen oder bei Vorliegen sonstiger berechtigter Gründe geben wir personenbezogene Daten nicht ohne Einwilligung des Nutzers an Dritte weiter.","privacy.5t":"5. Nutzung über ein Organisationskonto","privacy.5p":"Wenn ein Nutzer den Dienst über eine Organisation (Team, Unternehmen usw.), der er angehört, nutzt, kann der Administrator dieser Organisation auf die Kontoeinstellungen der Mitglieder sowie auf Daten wie Analyseergebnisse, Verständnis und Lernstand zugreifen. Der Umgang bei einer Nutzung auf Organisationsebene richtet sich auch nach den Richtlinien der betreffenden Organisation.","privacy.6t":"6. Aufbewahrung und Sicherheit","privacy.6p":"Die erhobenen Informationen werden unter Ergreifung angemessener technischer und organisatorischer Maßnahmen wie Verschlüsselung und Zugriffskontrolle auf einer Cloud-Plattform (Google Cloud) verwaltet.","privacy.7t":"7. Aufbewahrungsdauer und Löschung","privacy.7p":"Informationen werden für den zur Erreichung des Verwendungszwecks erforderlichen Zeitraum aufbewahrt und nach Ablauf dieses Zeitraums oder auf Verlangen des Nutzers ordnungsgemäß gelöscht oder anonymisiert. Mit der Löschung des Kontos werden die zugehörigen Daten gelöscht.","privacy.8t":"8. Grenzüberschreitende Datenübermittlung","privacy.8p":"Der Dienst nutzt eine Cloud-Plattform (Google Cloud) sowie eine KI-Analyseplattform, sodass die Daten der Nutzer unter Umständen auf Servern außerhalb Japans (z. B. in den USA) gespeichert und verarbeitet werden. Auch in diesem Fall ergreifen wir gemäß den anwendbaren Gesetzen angemessene Schutzmaßnahmen.","privacy.9t":"9. Rechtsgrundlage der Verarbeitung (für Nutzer im EEA / Vereinigten Königreich)","privacy.9p":"Für Nutzer im Europäischen Wirtschaftsraum (EEA) oder im Vereinigten Königreich verarbeiten wir personenbezogene Daten auf Grundlage der GDPR u. a. mit einer der folgenden Rechtsgrundlagen: (1) Erfüllung eines Vertrags, (2) Erfüllung rechtlicher Verpflichtungen, (3) berechtigte Interessen (Gewährleistung der Sicherheit und Verbesserung des Dienstes usw.), (4) Einwilligung des Nutzers. Eine auf Einwilligung beruhende Verarbeitung kann jederzeit widerrufen werden.","privacy.10t":"10. Rechte der Nutzer","privacy.10p":"Nutzer können in Bezug auf ihre eigenen personenbezogenen Daten Auskunft, Berichtigung, Löschung, Nutzungsstopp usw. verlangen. Bei einem solchen Antrag bitten wir zur Identitätsprüfung gegebenenfalls um die Angabe zusätzlicher Informationen. Je nach den Gesetzen Ihrer Region (GDPR, CCPA usw.) können zusätzliche Rechte wie Datenübertragbarkeit oder Widerspruch gegen die Verarbeitung bestehen. Bitte wenden Sie sich an unsere Kontaktstelle.","privacy.11t":"11. Verwendung von Cookies","privacy.11p":"Der Dienst verwendet die für die Aufrechterhaltung des Anmeldestatus und die Gewährleistung der Sicherheit erforderlichen Cookies (notwendige Cookies). Cookies zu Werbe- oder Tracking-Zwecken werden nicht verwendet. Über Browsereinstellungen oder DNT-/GPC-Signale lassen sich Cookies steuern; werden jedoch notwendige Cookies deaktiviert, können einige Funktionen unter Umständen nicht mehr genutzt werden.","privacy.12t":"12. Änderung dieser Richtlinie","privacy.12p":"Diese Richtlinie kann bei Gesetzesänderungen oder Änderungen der Dienstinhalte überarbeitet werden. Bei wesentlichen Änderungen weisen wir im Dienst darauf hin.","privacy.13t":"13. Kontakt","privacy.13p":"Bei Fragen zu dieser Richtlinie wenden Sie sich bitte an den Betreiber des Dienstes.","privacy.updated":"Zuletzt aktualisiert: 6. Juli 2026"}};

  function getCookie(name) {
    var m = document.cookie.match(new RegExp("(?:^|; )" + name + "=([^;]*)"));
    return m ? decodeURIComponent(m[1]) : null;
  }
  function setLocaleStores(loc) {
    document.cookie = COOKIE + "=" + loc + "; path=/; max-age=31536000; samesite=lax";
    try { localStorage.setItem(COOKIE, loc); } catch (e) {}
  }
  function detect() {
    var c = getCookie(COOKIE);
    if (LOCALES.indexOf(c) >= 0) return c;
    try {
      var ls = localStorage.getItem(COOKIE);
      if (LOCALES.indexOf(ls) >= 0) return ls;
    } catch (e) {}
    return "ja";
  }

  var baseline = {};
  function cacheBaseline() {
    document.querySelectorAll("[data-i18n]").forEach(function (el) {
      baseline[el.getAttribute("data-i18n")] = el.innerHTML;
    });
  }
  function apply(loc) {
    var dict = DICT[loc];
    document.querySelectorAll("[data-i18n]").forEach(function (el) {
      var k = el.getAttribute("data-i18n");
      var v = loc === "ja" || !dict ? baseline[k] : dict[k] != null ? dict[k] : baseline[k];
      if (v != null) el.innerHTML = v;
    });
    document.documentElement.setAttribute("lang", loc);
  }
  function setLocale(loc) {
    if (LOCALES.indexOf(loc) < 0) loc = "ja";
    setLocaleStores(loc);
    apply(loc);
  }

  function init() {
    cacheBaseline();
    var loc = detect();
    var sel = document.getElementById("lang-select");
    if (sel) {
      sel.value = loc;
      sel.addEventListener("change", function () { setLocale(sel.value); });
    }
    if (loc !== "ja") apply(loc);
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();
